const products = $('Load Products').all().map(i => i.json || {}).filter(p => p.product_key);
const rows = $('Load Presenter Queue').all().map(i => i.json || {});

const countBy = {};
for (const r of rows) {
  const m = String(r.reel_key || '').match(/^pre_(.+)_v\d+$/);
  if (m) countBy[m[1]] = (countBy[m[1]] || 0) + 1;
}
const eligible = products
  .map(p => ({ p, n: countBy[p.product_key] || 0 }))
  .filter(e => e.n < 4)
  .sort((a, b) => a.n - b.n);
if (!eligible.length) return [];

const prod = eligible[0].p;
const variationNo = eligible[0].n + 1;
const name = String(prod.product_name || prod.product_key);
const packshot = String(prod.packshot_image_url || '');
if (!packshot) return [];
const keySpecs = String(prod.key_specs || '').trim();
const category = String(prod.category || '').trim();

// SPOKEN-TEXT RULE: no brand names, no prices in scene.text (user decision 2026-11-19).
const CAT_SPOKEN = {
  beauty_skincare: 'ein Hautpflege-Produkt',
  car_smart_accessories: 'ein praktisches Auto-Zubehör',
  smart_home_everyday: 'ein praktisches Haushalts-Gadget',
  tech_desk_gadgets: 'ein nützliches Tech-Gadget'
};
const spokenTerm = CAT_SPOKEN[category] || 'ein praktisches Produkt';
const sanitizeSpoken = (t) => t
  .split(name).join('das Produkt')
  .replace(/\b\d+[.,]?\d*\s?(euro|eur|€)\b/gi, '')
  .replace(/\s{2,}/g, ' ')
  .trim();

const PRESENTER_IMG = 'https://files.catbox.moe/zaisoi.png';
const PRESENTER_PROMPT = 'The same woman from the reference image speaks naturally to the camera in the same bright room. Preserve her identity, hairstyle, clothing and facial features. Restrained, realistic articulation with modest jaw openings and relaxed lips. Subtle head movements and natural blinking. After the spoken sentence ends, she rests with her mouth gently closed. Static camera, no cuts, no new objects.';

const specSentence = sanitizeSpoken(keySpecs.split(/(?<=[.!?])\s/)[0] || '').slice(0, 160);
const usageText = specSentence.length > 15
  ? 'Laut Anbieter: ' + specSentence
  : 'Die genaue Anwendung und alle Details stehen in der Produktbeschreibung im Shop.';

// SEO caption: product name + spec snippet (dedupe: skip leading product-name repeat) + hashtags.
let specSnippet = keySpecs.replace(/\s+/g, ' ').trim();
if (specSnippet.toLowerCase().startsWith(name.toLowerCase().slice(0, 40))) specSnippet = specSnippet.slice(name.length).replace(/^[ ,\-\u2013]+/, '');
specSnippet = specSnippet.slice(0, 120).trim();
const nameLower = name.toLowerCase();
let catTags = { beauty_skincare: '#skincare #beautyde', car_smart_accessories: '#autozubehör #carhacks', smart_home_everyday: '#haushalt #cleaninghacks', tech_desk_gadgets: '#techgadgets #desksetup' }[category] || '';
if (/licht|lampe|projektor|led/.test(nameLower)) catTags = '#lichtprojektor #roomdeco';
else if (/reinig|schrubber|buerste|dampf/.test(nameLower)) catTags = '#cleaninghacks #putzen';
else if (/gesicht|haut|serum|creme|maske/.test(nameLower)) catTags = '#skincare #beautyde';
const hashtags = ['#tiktokshopde', '#tiktokmademebuyit', catTags, '#bizpunk72'].filter(Boolean).join(' ');
const caption = (name + (specSnippet ? ' ' + specSnippet : '') + ' - Details im verlinkten TikTok Shop. ' + hashtags).slice(0, 500);

const spec = {
  product_id: prod.product_key,
  pack_quantity: 'Standard',
  presenter_image_url: PRESENTER_IMG,
  caption_de: caption,
  scenes: [
    { id: 'hook', kind: 'presenter', text: 'Du suchst ' + spokenTerm + '?', prompt: PRESENTER_PROMPT },
    { id: 'product', kind: 'images', text: 'Dieses Angebot zeigt ' + spokenTerm + '.', images: [packshot] },
    { id: 'usage', kind: 'images', text: usageText, images: [packshot] },
    { id: 'selection', kind: 'images', text: 'Vor dem Kauf lohnt ein Blick auf Varianten, Mengenangaben und die vollstaendige Produktbeschreibung.', images: [packshot] },
    { id: 'cta', kind: 'presenter', text: 'Die Produktdetails findest du im verlinkten TikTok Shop.', prompt: PRESENTER_PROMPT }
  ]
};

const reelKey = 'pre_' + prod.product_key + '_v' + variationNo;
return [{ json: { reel_key: reelKey, spec_json: JSON.stringify(spec), status: 'queued', zernio_post_id: '', error: '', product_name: name, packshot_url: packshot } }];

